export interface AnalysisResult {
  id: string;
  fileName: string;
  url: string;
  category: string;
  description: string;
  tags: string[];
  confidence: number;
  timestamp: number;
  status: 'pending' | 'processing' | 'completed' | 'error';
  error?: string;
}

export interface Stats {
