import { GoogleGenAI, Type, GenerateContentResponse } from "@google/genai";

const MODEL_NAME = 'gemini-3-flash-preview';

export const analyzeImage = async (
  base64Data: string,
  mimeType: string,
  categories: string[] = []
): Promise<any> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const categoryContext = categories.length > 0 
    ? `Available categories: ${categories.join(', ')}. Try to pick the most relevant one.`
    : "Determine a high-level category for this image (e.g., Landscape, Portrait, Document, Macro, Street, etc.)";

  const response = await ai.models.generateContent({
    model: MODEL_NAME,
    contents: {
      parts: [
        {
          inlineData: {
            mimeType,
            data: base64Data
          }
        },
        {
          text: `Analyze this image and return a JSON object. ${categoryContext} 
          Provide a brief description (max 10 words) and 5 relevant tags.`
        }
      ]
    },
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          category: { type: Type.STRING },
          description: { type: Type.STRING },
          tags: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          },
          confidence: { type: Type.NUMBER, description: "Confidence score between 0 and 1" }
        },
        required: ["category", "description", "tags", "confidence"]
      }
    }
  });

  try {
    const result = JSON.parse(response.text || '{}');
    return result;
  } catch (err) {
    console.error("Failed to parse Gemini response", err);
    throw new Error("Invalid response format from AI");
  }
};

