import React, { useState, useCallback, useRef, useEffect } from 'react';
import { 
  FolderOpen, 
  Play, 
  Pause, 
  CheckCircle, 
  AlertCircle, 
  Download, 
  LayoutGrid, 
  Settings,
  Image as ImageIcon,
  Zap,
  Trash2,
  Filter
} from 'lucide-react';
import { AnalysisResult, ProcessingMode } from './types';
import { analyzeImage } from './services/geminiService';
import ImageCard from './components/ImageCard';
